/**
 * AccountingManagement.gs
 * 회계 기능 관련 서버 함수
 * Hot Potato Accounting Management System
 */

// ===== 증빙 하위 폴더 이름 (.env VITE_FOLER_NAME.ACCOUNT_EVIDENCE 와 동기화) =====

/**
 * 웹앱 요청 필드 → 스크립트 속성 EVIDENCE_FOLDER_NAME → 기본 evidence
 * (요청에 camelCase/snake_case/별칭 accountEvidence 모두 허용. 예전 속성값이 '증빙'이면 요청 없을 때만 그 이름이 쓰임.)
 * @param {Object} params - createLedger 요청 본문
 * @returns {string}
 */
function getEvidenceFolderNameFromParams_(params) {
  var p = params || {};
  var candidates = [
    p.evidenceFolderName,
    p.evidence_folder_name,
    p.accountEvidence,
    p.account_evidence,
    p.ACCOUNT_EVIDENCE
  ];
  if (p.data != null && typeof p.data === 'object') {
    candidates.push(p.data.evidenceFolderName);
    candidates.push(p.data.evidence_folder_name);
    candidates.push(p.data.accountEvidence);
    candidates.push(p.data.account_evidence);
    candidates.push(p.data.ACCOUNT_EVIDENCE);
  }
  var i;
  for (i = 0; i < candidates.length; i++) {
    if (candidates[i] != null && String(candidates[i]).trim() !== '') {
      return String(candidates[i]).trim();
    }
  }
  var prop = PropertiesService.getScriptProperties().getProperty('EVIDENCE_FOLDER_NAME');
  if (prop && String(prop).trim()) {
    return String(prop).trim();
  }
  return 'evidence';
}

/**
 * 장부 폴더 하위에서 증빙 폴더 탐색 (현재 설정명 → 레거시 '증빙' → 'evidence')
 * @param {GoogleAppsScript.Drive.Folder} ledgerFolder
 * @param {Object} params - getLedgerList 는 {};
 * @returns {GoogleAppsScript.Drive.Folder|null}
 */
function findEvidenceSubFolderInLedger_(ledgerFolder, params, knownSubfolders) {
  var primary = getEvidenceFolderNameFromParams_(params || {});
  var tryNames = [primary];
  if (tryNames.indexOf('증빙') === -1) tryNames.push('증빙');
  if (tryNames.indexOf('evidence') === -1) tryNames.push('evidence');
  var subs = knownSubfolders || [];
  if (!knownSubfolders) {
    var it = ledgerFolder.getFolders();
    while (it.hasNext()) {
      subs.push(it.next());
    }
  }
  for (var i = 0; i < tryNames.length; i++) {
    var want = tryNames[i];
    for (var j = 0; j < subs.length; j++) {
      var subName = typeof subs[j].getName === 'function' ? subs[j].getName() : subs[j].name;
      if (subName === want) return subs[j];
    }
  }
  return null;
}

/**
 * 회계 최상위에 잘못 올라간 증빙 전용 폴더처럼 보이는 이름인지 (목록에서 제외)
 * @param {string} folderName
 * @returns {boolean}
 */
function isLikelyMisplacedEvidenceRootFolder_(folderName) {
  if (folderName === '증빙' || folderName === 'evidence') return true;
  var p = PropertiesService.getScriptProperties().getProperty('EVIDENCE_FOLDER_NAME');
  return !!(p && String(p).trim() === folderName);
}

// ===== 회계 폴더 초기화 =====

var accountingFolderIdMemo_ = null;
var ACCOUNTING_FOLDER_CACHE_PREFIX_ = 'accountingFolderId:';

function accountingFolderCacheKey_(rootFolderId) {
  return ACCOUNTING_FOLDER_CACHE_PREFIX_ + rootFolderId;
}

/**
 * 회계 폴더 초기화 (없으면 생성)
 * @returns {string} 회계 폴더 ID
 */
function initializeAccountingFolder() {
  if (accountingFolderIdMemo_) return accountingFolderIdMemo_;

  try {
    const cache = CacheService.getScriptCache();

    // 루트 폴더 찾기 (스크립트 속성 또는 기본값)
    const rootFolderName = PropertiesService.getScriptProperties().getProperty('ROOT_FOLDER_NAME') || 'hot_potato_remake';
    const accountingFolderName = PropertiesService.getScriptProperties().getProperty('ACCOUNT_FOLDER_NAME') || 'account';

    let rootFolder = null;
    const rootFolderId = getProjectRootFolderId_();
    if (rootFolderId) {
      try {
        rootFolder = DriveApp.getFolderById(rootFolderId);
      } catch (error) {
        logWarn_('AccountingManagement', '캐시된 루트 폴더를 열 수 없어 이름으로 다시 찾습니다:', error.message);
      }
    }
    if (!rootFolder) {
      const rootFolders = DriveApp.getFoldersByName(rootFolderName);
      if (!rootFolders.hasNext()) {
        throw new Error('루트 폴더를 찾을 수 없습니다: ' + rootFolderName);
      }
      rootFolder = rootFolders.next();
    }

    const cacheKey = accountingFolderCacheKey_(rootFolder.getId());
    const cachedId = cache.get(cacheKey);
    if (cachedId) {
      try {
        DriveApp.getFolderById(cachedId).getName();
        accountingFolderIdMemo_ = cachedId;
        return accountingFolderIdMemo_;
      } catch (error) {
        cache.remove(cacheKey);
      }
    }

    // 회계 폴더 찾기 또는 생성
    let accountingFolder;
    const folders = rootFolder.getFoldersByName(accountingFolderName);

    if (folders.hasNext()) {
      accountingFolder = folders.next();
      logDebug_('AccountingManagement', '기존 회계 폴더 발견:', accountingFolder.getId());
    } else {
      accountingFolder = rootFolder.createFolder(accountingFolderName);
      logDebug_('AccountingManagement', '새 회계 폴더 생성:', accountingFolder.getId());
    }

    accountingFolderIdMemo_ = accountingFolder.getId();
    cache.put(cacheKey, accountingFolderIdMemo_, 6 * 60 * 60);
    return accountingFolderIdMemo_;

  } catch (error) {
    logError_('AccountingManagement', '회계 폴더 초기화 오류:', error);
    throw new Error('회계 폴더 초기화 중 오류가 발생했습니다: ' + error.message);
  }
}

/**
 * 역할 코드를 그룹 이메일로 변환
 * @param {Array<string>} roleCodes - 역할 코드 배열 (예: ['std_council', 'professor'])
 * @returns {Array<string>} 그룹 이메일 배열
 */
function convertRoleCodesToGroupEmails(roleCodes) {
  try {
    if (!roleCodes || !Array.isArray(roleCodes) || roleCodes.length === 0) {
      return [];
    }

    // CONFIG.gs의 getGroupEmailByRole 함수 사용
    return roleCodes
      .map(role => getGroupEmailByRole(role))
      .filter(email => email && email.trim() !== '');

  } catch (error) {
    logError_('AccountingManagement', '역할 코드 변환 오류:', error);
    return [];
  }
}

// ===== 장부 폴더 권한 설정 =====

/**
 * 장부 폴더 권한 설정
 * @param {Object} params
 *   {
 *     folderId: string,           // 폴더 ID
 *     users: Array<string>,       // 사용자 이메일 목록
 *     groups: Array<string>       // 그룹 이메일 목록
 *   }
 * @returns {Object} 권한 설정 결과
 */
function setLedgerFolderPermissions(params) {
  try {
    const { folderId, users = [], groups = [] } = params;

    if (!folderId) {
      throw new Error('폴더 ID가 필요합니다');
    }

    let successCount = 0;
    let failCount = 0;
    const grantedUsers = [];
    const failedUsers = [];

    // 현재 권한 확인 (Drive API 사용)
    const permissions = { items: listPermissions_(folderId) };
    const beforePermissions = permissions.items || [];

    // 개인 사용자 권한 부여 (Drive API - 메일 알림 없음)
    for (const userEmail of users) {
      try {
        // 이미 권한이 있는지 확인
        const hasPermission = beforePermissions.some(p => p.emailAddress === userEmail && p.role === 'writer');
        if (hasPermission) {
          successCount++;
          grantedUsers.push(userEmail);
          continue;
        }

        // 편집 권한 부여 (메일 알림 없이)
        grantPermission_(folderId, 'user', userEmail, 'writer');
        successCount++;
        grantedUsers.push(userEmail);

        Utilities.sleep(100); // API 제한 방지

      } catch (error) {
        logError_('AccountingManagement', '사용자 권한 부여 실패:', error.message);
        failCount++;
        failedUsers.push(userEmail);
      }
    }

    // 그룹 권한 부여 (Google Groups) - Drive API 사용
    for (const groupEmail of groups) {
      try {
        // 그룹에 편집 권한 부여 (메일 알림 없이)
        grantPermission_(folderId, 'group', groupEmail, 'writer');
        successCount++;
        grantedUsers.push(groupEmail);

        Utilities.sleep(100);

      } catch (error) {
        logError_('AccountingManagement', '그룹 권한 부여 실패:', error.message);
        failCount++;
        failedUsers.push(groupEmail);
      }
    }

    return {
      success: successCount > 0,
      successCount: successCount,
      failCount: failCount,
      grantedUsers: grantedUsers,
      failedUsers: failedUsers
    };

  } catch (error) {
    logError_('AccountingManagement', '폴더 권한 설정 오류:', error);
    return {
      success: false,
      message: '폴더 권한 설정 중 오류가 발생했습니다: ' + error.message
    };
  }
}

/**
 * 스프레드시트 권한 설정
 * @param {Object} params
 *   {
 *     fileId: string,           // 파일 ID
 *     users: Array<string>,     // 사용자 이메일 목록
 *     groups: Array<string>     // 그룹 이메일 목록
 *   }
 * @returns {Object} 권한 설정 결과
 */
function setLedgerFilePermissions(params) {
  try {
    const { fileId, users = [], groups = [] } = params;

    if (!fileId) {
      throw new Error('파일 ID가 필요합니다');
    }

    let successCount = 0;
    let failCount = 0;
    const grantedUsers = [];
    const failedUsers = [];

    // 현재 권한 확인 (Drive API 사용)
    const permissions = { items: listPermissions_(fileId) };
    const beforePermissions = permissions.items || [];

    // 개인 사용자 권한 부여 (Drive API - 메일 알림 없음)
    for (const userEmail of users) {
      try {
        const hasPermission = beforePermissions.some(p => p.emailAddress === userEmail && p.role === 'writer');
        if (hasPermission) {
          successCount++;
          grantedUsers.push(userEmail);
          continue;
        }

        // 편집 권한 부여 (메일 알림 없이)
        grantPermission_(fileId, 'user', userEmail, 'writer');
        successCount++;
        grantedUsers.push(userEmail);

        Utilities.sleep(100);

      } catch (error) {
        logError_('AccountingManagement', '사용자 권한 부여 실패:', error.message);
        failCount++;
        failedUsers.push(userEmail);
      }
    }

    // 그룹 권한 부여 (Drive API - 메일 알림 없음)
    for (const groupEmail of groups) {
      try {
        // 그룹에 편집 권한 부여 (메일 알림 없이)
        grantPermission_(fileId, 'group', groupEmail, 'writer');
        successCount++;
        grantedUsers.push(groupEmail);

        Utilities.sleep(100);

      } catch (error) {
        logError_('AccountingManagement', '그룹 권한 부여 실패:', error.message);
        failCount++;
        failedUsers.push(groupEmail);
      }
    }

    return {
      success: successCount > 0,
      successCount: successCount,
      failCount: failCount,
      grantedUsers: grantedUsers,
      failedUsers: failedUsers
    };

  } catch (error) {
    logError_('AccountingManagement', '스프레드시트 권한 설정 오류:', error);
    return {
      success: false,
      message: '스프레드시트 권한 설정 중 오류가 발생했습니다: ' + error.message
    };
  }
}

/**
 * 증빙 폴더 권한 설정
 * @param {Object} params
 *   {
 *     folderId: string,           // 폴더 ID
 *     users: Array<string>,       // 사용자 이메일 목록
 *     groups: Array<string>       // 그룹 이메일 목록
 *   }
 * @returns {Object} 권한 설정 결과
 */
function setEvidenceFolderPermissions(params) {
  // setLedgerFolderPermissions와 동일한 로직
  return setLedgerFolderPermissions(params);
}

// ===== 회계 관련 시트 생성 =====

/**
 * 회계 관련 시트 생성
 * @param {SpreadsheetApp.Spreadsheet} spreadsheet - 스프레드시트 객체
 */
function createAccountingSheets(spreadsheet) {
  try {

    // 기본 시트 삭제 (필요시)
    const sheets = spreadsheet.getSheets();
    const defaultSheet = sheets.length > 0 ? sheets[0] : null;

    // 통장 시트 생성
    const accountSheet = spreadsheet.insertSheet('통장');
    setSheetHeaders(accountSheet, [
      'account_id', 'account_name', 'initial_balance', 'current_balance',
      'main_manager_id', 'sub_manager_ids', 'access_group_emails', 'access_user_emails',
      'created_by', 'created_date', 'is_active'
    ]);

    // 장부 시트 생성
    const ledgerSheet = spreadsheet.insertSheet('장부');
    setSheetHeaders(ledgerSheet, [
      'entry_id', 'account_id', 'date', 'category', 'description',
      'amount', 'balance_after', 'source', 'transaction_type',
      'evidence_file_id', 'evidence_file_name',
      'created_by', 'created_date', 'is_budget_executed', 'budget_plan_id'
    ]);

    // 예산계획 시트 생성
    const budgetSheet = spreadsheet.insertSheet('예산계획');
    setSheetHeaders(budgetSheet, [
      'budget_id', 'account_id', 'title', 'total_amount',
      'requested_date', 'planned_execution_date', 'status',
      'sub_manager_reviewed', 'sub_manager_review_date',
      'main_manager_approved', 'main_manager_approval_date',
      'executed_date', 'created_by', 'rejection_reason', 'details'
    ]);

    // 카테고리 시트 생성
    const categorySheet = spreadsheet.insertSheet('카테고리');
    setSheetHeaders(categorySheet, [
      'category_id', 'category_name', 'description',
      'created_by', 'created_date', 'is_active', 'usage_count'
    ]);

    // 기본 시트 삭제
    if (defaultSheet && defaultSheet.getName() === '시트1') {
      spreadsheet.deleteSheet(defaultSheet);
    }

  } catch (error) {
    logError_('AccountingManagement', '시트 생성 오류:', error);
    throw error;
  }
}

/**
 * 시트 헤더 설정
 */
function setSheetHeaders(sheet, headers) {
  try {
    const headerRange = sheet.getRange(1, 1, 1, headers.length);
    headerRange.setValues([headers]);
    headerRange.setFontWeight('bold');
    headerRange.setBackground('#f0f0f0');
  } catch (error) {
    logError_('AccountingManagement', '헤더 설정 오류:', error);
    throw error;
  }
}

// ===== 장부 구조 생성 =====

/**
 * 장부 구조 생성 (폴더 + 스프레드시트 + 증빙 폴더 + 권한 설정)
 * @param {Object} params - 생성 파라미터
 *   {
 *     ledgerName: string,              // 장부 이름
 *     accountName: string,             // 통장 이름 (장부마다 통장 하나)
 *     initialBalance: number,          // 최초 잔액
 *     creatorEmail: string,            // 생성자 이메일
 *     accessUsers: Array<string>,      // 접근 권한 사용자 이메일 목록
 *     accessGroups: Array<string>,     // 접근 권한 그룹 역할 코드 (예: ['std_council', 'professor'])
 *     mainManagerEmail: string,        // 주관리인 이메일
 *     subManagerEmails: Array<string>  // 별도 관리인 이메일 목록
 *   }
 * @returns {Object} 생성된 구조 정보 및 권한 설정 결과
 */
function createLedgerStructure(params) {
  try {

    const {
      ledgerName,
      accountName,
      initialBalance = 0,
      creatorEmail,
      accessUsers = [],
      accessGroups = [],
      mainManagerEmail,
      subManagerEmails = []
    } = params;

    // 1. 회계 폴더 초기화
    const accountingFolderId = initializeAccountingFolder();
    const accountingFolder = DriveApp.getFolderById(accountingFolderId);

    // 2. 장부 폴더 생성
    const ledgerFolder = accountingFolder.createFolder(ledgerName);
    const ledgerFolderId = ledgerFolder.getId();
    logDebug_('AccountingManagement', '장부 폴더 생성:', ledgerFolderId);

    // 3. 스프레드시트 생성
    const spreadsheet = SpreadsheetApp.create(`${ledgerName}_장부`);
    const spreadsheetId = spreadsheet.getId();
    const spreadsheetFile = DriveApp.getFileById(spreadsheetId);

    // 스프레드시트를 장부 폴더로 이동
    ledgerFolder.addFile(spreadsheetFile);
    DriveApp.getRootFolder().removeFile(spreadsheetFile);

    // 시트 생성 (통장, 장부, 예산계획, 카테고리)
    createAccountingSheets(spreadsheet);

    // 통장 정보를 통장 시트에 추가 (장부마다 통장 하나)
    if (accountName) {
      const accountSheet = spreadsheet.getSheetByName('통장');
      if (accountSheet) {
        const accountId = 'acc_' + Date.now();
        const createdDate = new Date().toISOString();

        // 주관리인 ID는 이메일에서 추출 (또는 그대로 사용)
        const mainManagerId = mainManagerEmail;
        const subManagerIdsJson = JSON.stringify(subManagerEmails || []);
        const groupEmailsJson = JSON.stringify(convertRoleCodesToGroupEmails(accessGroups));
        const userEmailsJson = JSON.stringify(accessUsers || []);

        accountSheet.appendRow([
          accountId,
          accountName,
          initialBalance,
          initialBalance, // current_balance = initial_balance
          mainManagerId,
          subManagerIdsJson,
          groupEmailsJson,
          userEmailsJson,
          creatorEmail,
          createdDate,
          'TRUE' // is_active
        ]);
      }
    }

    logDebug_('AccountingManagement', '스프레드시트 생성:', spreadsheetId);

    // 4. 증빙 폴더 생성 (프론트 evidenceFolderName / 스크립트 속성 EVIDENCE_FOLDER_NAME)
    const evidenceFolderLabel = getEvidenceFolderNameFromParams_(params);
    const evidenceFolder = ledgerFolder.createFolder(evidenceFolderLabel);
    const evidenceFolderId = evidenceFolder.getId();
    logDebug_('AccountingManagement', '증빙 폴더 생성:', evidenceFolderLabel, evidenceFolderId);

    // 5. 권한 설정
    // 접근 권한 대상: 생성자 + 주관리인 + 별도 관리인 + 지정된 사용자
    const allAccessUsers = [
      creatorEmail,
      mainManagerEmail,
      ...subManagerEmails,
      ...accessUsers
    ].filter((email, index, arr) => 
      email && email.trim() !== '' && arr.indexOf(email) === index
    );

    // 역할 코드를 그룹 이메일로 변환
    const groupEmails = convertRoleCodesToGroupEmails(accessGroups);

    // 장부 폴더 권한 설정
    const folderPermissionResult = setLedgerFolderPermissions({
      folderId: ledgerFolderId,
      users: allAccessUsers,
      groups: groupEmails
    });

    // 스프레드시트 권한 설정
    const spreadsheetPermissionResult = setLedgerFilePermissions({
      fileId: spreadsheetId,
      users: allAccessUsers,
      groups: groupEmails
    });

    // 증빙 폴더 권한 설정
    const evidencePermissionResult = setEvidenceFolderPermissions({
      folderId: evidenceFolderId,
      users: allAccessUsers,
      groups: groupEmails
    });

    return {
      success: true,
      message: '장부가 성공적으로 생성되었습니다.',
      data: {
        ledgerFolderId: ledgerFolderId,
        spreadsheetId: spreadsheetId,
        evidenceFolderId: evidenceFolderId,
        resolvedEvidenceFolderName: evidenceFolderLabel,
        permissionResult: {
          folder: folderPermissionResult,
          spreadsheet: spreadsheetPermissionResult,
          evidence: evidencePermissionResult
        }
      }
    };

  } catch (error) {
    logError_('AccountingManagement', '장부 생성 오류:', error);
    return {
      success: false,
      message: '장부 생성 중 오류가 발생했습니다: ' + error.message
    };
  }
}

// ===== 장부 목록 조회 =====

/**
 * 장부 목록 조회
 * @returns {Array<Object>} 장부 목록
 */
/**
 * 장부 목록. req.userEmail이 있으면 그 사용자가 접근 대상으로 지정된 장부만 돌려준다.
 * (요청자 정보가 없으면 전체 — 편집기 실행·관리 함수용)
 */
function getLedgerList(req) {
  try {
    const accountingFolderId = initializeAccountingFolder();
    const folderResponse = Drive.Files.list({
      q: "'" + accountingFolderId + "' in parents and trashed=false and mimeType='application/vnd.google-apps.folder'",
      pageSize: 1000,
      fields: 'files(id,name,createdTime,parents)'
    });
    const ledgerFolders = folderResponse.files || [];
    const visibleLedgerFolders = ledgerFolders.filter(function(folder) {
      return !isLikelyMisplacedEvidenceRootFolder_(folder.name);
    });

    const childrenByParent = {};
    const parentChunkSize = 50;
    for (let offset = 0; offset < visibleLedgerFolders.length; offset += parentChunkSize) {
      const chunk = visibleLedgerFolders.slice(offset, offset + parentChunkSize);
      const parentQuery = chunk.map(function(folder) {
        return "'" + folder.id + "' in parents";
      }).join(' or ');
      if (!parentQuery) continue;

      const childResponse = Drive.Files.list({
        q: '(' + parentQuery + ") and trashed=false and (mimeType='application/vnd.google-apps.spreadsheet' or mimeType='application/vnd.google-apps.folder')",
        pageSize: 1000,
        fields: 'files(id,name,mimeType,parents)'
      });
      (childResponse.files || []).forEach(function(file) {
        (file.parents || []).forEach(function(parentId) {
          if (!childrenByParent[parentId]) childrenByParent[parentId] = [];
          childrenByParent[parentId].push(file);
        });
      });
    }

    const ledgers = visibleLedgerFolders.map(function(folder) {
      const folderName = folder.name;
      const children = childrenByParent[folder.id] || [];
      const spreadsheet = children.find(function(file) {
        return file.mimeType === 'application/vnd.google-apps.spreadsheet';
      });
      const subfolders = children.filter(function(file) {
        return file.mimeType === 'application/vnd.google-apps.folder';
      });
      const evidenceSub = findEvidenceSubFolderInLedger_(null, {}, subfolders);
      const evidenceFolderId = evidenceSub ? evidenceSub.id : null;

      return {
        folderId: folder.id,
        folderName: folderName,
        spreadsheetId: spreadsheet ? spreadsheet.id : '',
        evidenceFolderId: evidenceFolderId || '',
        createdDate: folder.createdTime || ''
      };
    });

    const userEmail = req && req.userEmail ? String(req.userEmail).toLowerCase() : '';
    if (!userEmail) return ledgers;
    const groupEmail = String(getGroupEmailByRole(req.userType) || '').toLowerCase();
    return ledgers.filter(function(ledger) {
      return isLedgerAccessibleBy_(ledger.spreadsheetId, userEmail, groupEmail);
    });

  } catch (error) {
    logError_('AccountingManagement', '장부 목록 조회 오류:', error);
    return [];
  }
}

/**
 * 장부 스프레드시트 ID 조회
 * @param {string} folderId - 장부 폴더 ID
 * @returns {string} 스프레드시트 ID
 */
function getLedgerSpreadsheetId(folderId) {
  try {
    const folder = DriveApp.getFolderById(folderId);
    const files = folder.getFiles();

    while (files.hasNext()) {
      const file = files.next();
      if (file.getMimeType() === 'application/vnd.google-apps.spreadsheet') {
        return file.getId();
      }
    }

    return null;

  } catch (error) {
    logError_('AccountingManagement', '스프레드시트 ID 조회 오류:', error);
    return null;
  }
}

/**
 * 통장 서브 관리자 목록 업데이트
 * @param {Object} req - 요청 데이터
 * @returns {Object} 업데이트 결과
 */
function updateAccountSubManagers(req) {
  try {
    const { spreadsheetId, accountId, subManagerEmails } = req;

    if (!spreadsheetId || !accountId) {
      return {
        success: false,
        message: '스프레드시트 ID와 통장 ID가 필요합니다.'
      };
    }

    const spreadsheet = SpreadsheetApp.openById(spreadsheetId);
    const accountSheet = spreadsheet.getSheetByName('통장');

    if (!accountSheet) {
      return {
        success: false,
        message: '통장 시트를 찾을 수 없습니다.'
      };
    }

    // 통장 데이터 찾기
    const data = accountSheet.getDataRange().getValues();
    const headers = data[0];
    const accountIdIndex = headers.indexOf('account_id');

    if (accountIdIndex === -1) {
      return {
        success: false,
        message: '통장 시트의 헤더를 찾을 수 없습니다.'
      };
    }

    // 해당 account_id를 가진 행 찾기
    let rowIndex = -1;
    for (let i = 1; i < data.length; i++) {
      if (data[i][accountIdIndex] === accountId) {
        rowIndex = i + 1; // 1-based index
        break;
      }
    }

    if (rowIndex === -1) {
      return {
        success: false,
        message: '통장을 찾을 수 없습니다.'
      };
    }

    // 서브 관리자 목록 업데이트 (sub_manager_ids 컬럼, 6번째 컬럼, F열)
    const subManagerIdsIndex = headers.indexOf('sub_manager_ids');
    if (subManagerIdsIndex === -1) {
      return {
        success: false,
        message: '서브 관리자 컬럼을 찾을 수 없습니다.'
      };
    }

    const subManagerIdsJson = JSON.stringify(subManagerEmails || []);
    accountSheet.getRange(rowIndex, subManagerIdsIndex + 1).setValue(subManagerIdsJson);

    return {
      success: true,
      message: '서브 관리자 목록이 성공적으로 업데이트되었습니다.',
      data: {
        accountId: accountId,
        subManagerEmails: subManagerEmails
      }
    };

  } catch (error) {
    logError_('AccountingManagement', '서브 관리자 목록 업데이트 오류:', error);
    return {
      success: false,
      message: '서브 관리자 목록 업데이트 중 오류가 발생했습니다: ' + error.message
    };
  }
}

/**
 * 장부 스프레드시트에서 카테고리 목록 가져오기
 * @param {string} spreadsheetId - 스프레드시트 ID
 * @returns {Array<string>} 카테고리 목록
 */
function getAccountingCategories(spreadsheetId) {
  try {

    if (!spreadsheetId) {
      throw new Error('스프레드시트 ID가 필요합니다');
    }

    const spreadsheet = SpreadsheetApp.openById(spreadsheetId);
    const sheets = spreadsheet.getSheets();

    if (sheets.length === 0) {
      logWarn_('AccountingManagement', '시트가 없습니다.');
      return [];
    }

    // 첫 번째 시트 사용
    const sheet = sheets[0];
    const sheetName = sheet.getName();
    logDebug_('AccountingManagement', '시트 이름:', sheetName);

    // 데이터 범위 가져오기 (A열에서 카테고리 찾기)
    const lastRow = sheet.getLastRow();
    if (lastRow < 2) {
      logWarn_('AccountingManagement', '데이터가 없습니다.');
      return [];
    }

    // 헤더 행 확인 (일반적으로 1행)
    const headerRange = sheet.getRange(1, 1, 1, sheet.getLastColumn());
    const headers = headerRange.getValues()[0];

    // 카테고리 열 찾기 (일반적으로 "카테고리", "분류", "항목" 등)
    let categoryColumnIndex = -1;
    for (let i = 0; i < headers.length; i++) {
      const header = String(headers[i]).toLowerCase().trim();
      if (header.includes('카테고리') || header.includes('분류') || header.includes('항목') || header.includes('category')) {
        categoryColumnIndex = i + 1; // 1-based index
        break;
      }
    }

    // 카테고리 열을 찾지 못한 경우 A열 사용
    if (categoryColumnIndex === -1) {
      categoryColumnIndex = 1;
      logDebug_('AccountingManagement', '카테고리 열을 찾지 못했습니다. A열을 사용합니다.');
    }

    // 카테고리 데이터 가져오기 (2행부터, 헤더 제외)
    const categoryRange = sheet.getRange(2, categoryColumnIndex, lastRow - 1, 1);
    const categoryValues = categoryRange.getValues();

    // 중복 제거 및 빈 값 제거
    const categories = [];
    const seen = new Set();

    for (let i = 0; i < categoryValues.length; i++) {
      const category = String(categoryValues[i][0]).trim();
      if (category && category !== '' && !seen.has(category)) {
        seen.add(category);
        categories.push(category);
      }
    }
    return categories;

  } catch (error) {
    logError_('AccountingManagement', '장부 카테고리 조회 오류:', error);
    return [];
  }
}


/**
 * 통장 시트에 저장된 접근 대상(생성자, 주·별도 관리인, 지정 사용자, 지정 그룹스)에 사용자가 포함되는지
 */
function isLedgerAccessibleBy_(spreadsheetId, userEmail, groupEmail) {
  if (!spreadsheetId) return false;
  try {
    const sheet = SpreadsheetApp.openById(spreadsheetId).getSheetByName('통장');
    if (!sheet) return false;
    const values = sheet.getDataRange().getValues();
    const header = values[0];
    const col = function(name) { return header.indexOf(name); };
    const parse = function(row, name) {
      try { return JSON.parse(row[col(name)] || '[]'); } catch (e) { return []; }
    };
    return values.slice(1).some(function(row) {
      const users = [row[col('main_manager_id')], row[col('created_by')]]
        .concat(parse(row, 'sub_manager_ids'), parse(row, 'access_user_emails'))
        .map(function(v) { return String(v || '').toLowerCase(); });
      const groups = parse(row, 'access_group_emails').map(function(v) { return String(v || '').toLowerCase(); });
      return users.indexOf(userEmail) !== -1 || (!!groupEmail && groups.indexOf(groupEmail) !== -1);
    });
  } catch (error) {
    logWarn_('AccountingManagement', '장부 접근 대상 확인 실패:', spreadsheetId, error.message);
    return false;
  }
}

// ===== 기존 장부 권한 재적용 (편집기에서 실행) =====

// 예전 기본값으로 저장된 그룹스 주소 → 그룹스 역할 키
const LEGACY_GROUP_EMAIL_ROLES_ = {
  'hp_supp@googlegroups.com': 'supp',
  'ad_professor_hp@googlegroups.com': 'ad_professor'
};

/**
 * 모든 장부의 통장 시트에 저장된 접근 대상(관리인, 그룹스, 사용자)으로 장부 폴더·스프레드시트·증빙 폴더 권한을 다시 부여한다.
 * 예전 기본값으로 저장된 그룹스 주소는 현재 GROUP_EMAIL_JSON 주소로 바꾸고 시트 값도 고친다.
 * 이미 있는 권한은 건너뛴다.
 */
function applyLedgerSharing() {
  const list = getLedgerList() || [];
  const lines = [];

  list.forEach(function(ledger) {
    if (!ledger.spreadsheetId) return;
    const sheet = SpreadsheetApp.openById(ledger.spreadsheetId).getSheetByName('통장');
    if (!sheet) {
      lines.push(ledger.folderName + ' | 통장 시트 없음');
      return;
    }

    const values = sheet.getDataRange().getValues();
    const header = values[0];
    const col = function(name) { return header.indexOf(name); };
    const users = [];
    const groups = [];

    values.slice(1).forEach(function(row, i) {
      const parse = function(name) {
        try { return JSON.parse(row[col(name)] || '[]'); } catch (e) { return []; }
      };
      const fixedGroups = parse('access_group_emails').map(function(email) {
        const role = LEGACY_GROUP_EMAIL_ROLES_[String(email).toLowerCase()];
        return role ? getGroupEmailByRole(role) : email;
      }).filter(Boolean);
      if (JSON.stringify(fixedGroups) !== JSON.stringify(parse('access_group_emails'))) {
        sheet.getRange(i + 2, col('access_group_emails') + 1).setValue(JSON.stringify(fixedGroups));
      }
      groups.push.apply(groups, fixedGroups);
      users.push(row[col('main_manager_id')], row[col('created_by')]);
      users.push.apply(users, parse('sub_manager_ids'));
      users.push.apply(users, parse('access_user_emails'));
    });

    const unique = function(arr) {
      return arr.filter(function(v, i) { return v && String(v).indexOf('@') > 0 && arr.indexOf(v) === i; });
    };
    const params = { users: unique(users), groups: unique(groups) };
    const targets = [
      ['폴더', setLedgerFolderPermissions, { folderId: ledger.folderId }],
      ['시트', setLedgerFilePermissions, { fileId: ledger.spreadsheetId }],
      ['증빙', setEvidenceFolderPermissions, { folderId: ledger.evidenceFolderId }]
    ];
    targets.forEach(function(t) {
      if (!t[2].folderId && !t[2].fileId) return;
      const result = t[1](Object.assign({}, t[2], params));
      lines.push(ledger.folderName + ' | ' + t[0] + ' | ' + (result.message || ('성공 ' + result.successCount + ', 실패 ' + result.failCount + (result.failedUsers && result.failedUsers.length ? ' (' + JSON.stringify(result.failedUsers) + ')' : ''))));
    });
    lines.push(ledger.folderName + ' | 그룹스: ' + params.groups.join(', '));
  });

  console.log('장부 권한 재적용 결과:\n' + lines.join('\n'));
  return lines;
}

/**
 * 증빙 파일 업로드 (프론트가 base64로 보낸 파일을 장부 증빙 폴더에 저장)
 * 사용자 드라이브 권한(drive.file)으로는 공유 증빙 폴더에 직접 올릴 수 없어서 서버가 대신 올린다.
 * 회계 폴더 아래 폴더만 허용한다.
 * @param {Object} req - { evidenceFolderId, fileName, mimeType, fileData(base64) }
 */
function uploadEvidenceFile(req) {
  try {
    if (!req.evidenceFolderId || !req.fileName || !req.fileData) {
      return { success: false, message: '증빙 폴더, 파일 이름, 내용이 필요합니다.' };
    }
    const folder = DriveApp.getFolderById(req.evidenceFolderId);
    if (!isFolderUnderRoot_(folder, initializeAccountingFolder(), {}, 0)) {
      return { success: false, message: '증빙 폴더가 아닙니다.' };
    }
    const blob = Utilities.newBlob(Utilities.base64Decode(req.fileData), req.mimeType || 'application/octet-stream', req.fileName);
    const file = folder.createFile(blob);
    return { success: true, data: { fileId: file.getId(), fileName: file.getName() } };
  } catch (error) {
    logError_('AccountingManagement', '증빙 파일 업로드 오류:', error);
    return { success: false, message: '증빙 파일 업로드 중 오류가 발생했습니다: ' + error.message };
  }
}

/**
 * AnnouncementManagement.gs
 * 공지사항 관리 관련 함수들
 * Hot Potato Admin Key Management System
 */

// ===== 공지사항 관리 함수들 =====

/**
 * 공지사항 시트 이름 가져오기 (스크립트 속성)
 * @returns {string} 시트 이름
 */
function getNoticeSheetName() {
  return PropertiesService.getScriptProperties().getProperty('NOTICE_SHEET_NAME') || '시트1';
}

/**
 * 공지 데이터가 있는 탭(시트) 찾기
 * 우선순위: 요청 sheetName(프론트 .env) → NOTICE_SHEET_NAME → '시트1' → 첫 번째 시트
 * @param {GoogleAppsScript.Spreadsheet.Spreadsheet} spreadsheet
 * @param {Object} req
 * @returns {GoogleAppsScript.Spreadsheet.Sheet|null}
 */
function resolveNoticeSheet_(spreadsheet, req) {
  if (!spreadsheet) return null;
  var candidates = [];
  var fromReq = req && req.sheetName != null ? String(req.sheetName).trim() : '';
  if (!fromReq && req && req.noticeSheetName != null) {
    fromReq = String(req.noticeSheetName).trim();
  }
  if (fromReq) candidates.push(fromReq);
  var fromProp = getNoticeSheetName();
  if (fromProp && candidates.indexOf(fromProp) === -1) {
    candidates.push(fromProp);
  }
  if (candidates.indexOf('시트1') === -1) {
    candidates.push('시트1');
  }
  var i;
  for (i = 0; i < candidates.length; i++) {
    var nm = candidates[i];
    if (!nm) continue;
    var sh = spreadsheet.getSheetByName(nm);
    if (sh) return sh;
  }
  var sheets = spreadsheet.getSheets();
  return sheets && sheets.length ? sheets[0] : null;
}

/**
 * 사용자 시트 이름 가져오기 (스크립트 속성)
 * @returns {string} 시트 이름
 */
function getUserSheetName() {
  return PropertiesService.getScriptProperties().getProperty('SHEET_NAME_USER') || 'user';
}

/**
 * 공지사항 스프레드시트 가져오기
 * @param {string} spreadsheetName - 스프레드시트 이름
 * @returns {Object} 스프레드시트 객체
 */
function getAnnouncementSpreadsheet(spreadsheetName) {
  try {
    const props = PropertiesService.getScriptProperties();
    const configuredNoticeName = props.getProperty('NOTICE_SPREADSHEET_NAME') || '';
    const fallbackNoticeName = props.getProperty('SPREADSHEET_NAME_NOTICE') || '';

    const candidateNames = [configuredNoticeName, fallbackNoticeName, spreadsheetName, 'notice']
      .map(v => String(v || '').trim())
      .filter((v, i, arr) => !!v && arr.indexOf(v) === i);

    // 1) 이름으로 직접 검색
    for (let i = 0; i < candidateNames.length; i++) {
      const files = DriveApp.getFilesByName(candidateNames[i]);
      if (files.hasNext()) {
        const file = files.next();
        return SpreadsheetApp.openById(file.getId());
      }
    }

    // 2) 프로젝트 루트 하위 notice 폴더에서 첫 번째 스프레드시트 검색 (이름 불일치 fallback)
    const rootFolderId = getProjectRootFolderId_();
    if (rootFolderId) {
      const rootFolder = DriveApp.getFolderById(rootFolderId);
      const noticeFolderCandidates = ['notice', props.getProperty('NOTICE_FOLDER_NAME') || '']
        .map(v => String(v || '').trim())
        .filter((v, i, arr) => !!v && arr.indexOf(v) === i);

      for (let j = 0; j < noticeFolderCandidates.length; j++) {
        const noticeFolders = rootFolder.getFoldersByName(noticeFolderCandidates[j]);
        if (!noticeFolders.hasNext()) continue;
        const noticeFolder = noticeFolders.next();
        const noticeFiles = noticeFolder.getFilesByType(MimeType.GOOGLE_SHEETS);
        if (noticeFiles.hasNext()) {
          const noticeFile = noticeFiles.next();
          return SpreadsheetApp.openById(noticeFile.getId());
        }
      }
    }

    throw new Error(`스프레드시트를 찾을 수 없습니다: ${spreadsheetName} (candidates: ${candidateNames.join(', ')})`);
  } catch (error) {
    logError_('AnnouncementManagement', '공지사항 스프레드시트 가져오기 오류:', error);
    throw error;
  }
}

/**
 * 요청에 spreadsheetId가 있으면 우선 openById, 실패 시 spreadsheetName(또는 notice)으로 탐색
 * @param {Object} req
 * @returns {GoogleAppsScript.Spreadsheet.Spreadsheet}
 */
function openAnnouncementSpreadsheetFromRequest_(req) {
  var spreadsheetId = req && req.spreadsheetId != null ? String(req.spreadsheetId).trim() : '';
  var spreadsheetName = req && req.spreadsheetName != null ? String(req.spreadsheetName).trim() : '';
  if (spreadsheetId) {
    try {
      return SpreadsheetApp.openById(spreadsheetId);
    } catch (e) {
      logWarn_('AnnouncementManagement', 'spreadsheetId로 공지 스프레드시트 열기 실패, 이름 탐색으로 폴백:', e);
    }
  }
  var nameForLookup = spreadsheetName || 'notice';
  return getAnnouncementSpreadsheet(nameForLookup);
}

/**
 * 공지 스프레드시트 참조: ID 또는 이름 중 하나 필요
 * @param {Object} req
 * @returns {boolean}
 */
function hasAnnouncementSheetRef_(req) {
  var id = req && req.spreadsheetId != null ? String(req.spreadsheetId).trim() : '';
  var name = req && req.spreadsheetName != null ? String(req.spreadsheetName).trim() : '';
  return !!id || !!name;
}

/**
 * user 시트 승인 컬럼 호환 체크 (approval / Approval)
 * @param {Object} userRow
 * @returns {boolean}
 */
function isApprovedUser_(userRow) {
  var status = String(
    (userRow && (userRow.approval !== undefined ? userRow.approval : userRow.Approval)) || ''
  ).trim().toUpperCase();
  return status === 'O';
}

/**
 * 승인된 사용자 이메일을 회원번호로 매핑한다.
 * @returns {Object<string, *>}
 */
function buildApprovedMemberIndex_() {
  const index = {};
  const spreadsheet = getHpMemberSpreadsheet();
  if (!spreadsheet) return index;

  const data = getSheetData(spreadsheet.getId(), getUserSheetName(), 'A:G');
  if (!data || data.length <= 1) return index;

  const header = data[0];
  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    const user = {};
    header.forEach((key, columnIndex) => {
      user[key] = row[columnIndex];
    });
    const encryptedEmail = user.google_member;
    if (encryptedEmail && isApprovedUser_(user) && !Object.prototype.hasOwnProperty.call(index, encryptedEmail)) {
      index[encryptedEmail] = user.no_member;
    }
  }
  return index;
}

/**
 * 공지에 저장된 암호화 이메일을 승인 회원번호로 변환한다.
 * @param {string} encryptedEmail
 * @param {Object<string, *>} memberIndex
 * @param {Object<string, *>} writerMemo
 * @param {string=} decryptedEmail
 * @returns {*}
 */
function resolveApprovedMemberId_(encryptedEmail, memberIndex, writerMemo, decryptedEmail) {
  if (!encryptedEmail) return '';
  if (Object.prototype.hasOwnProperty.call(writerMemo, encryptedEmail)) {
    return writerMemo[encryptedEmail];
  }

  let memberId = '';
  try {
    const email = decryptedEmail || decryptEmailMain(encryptedEmail);
    const variants = getEncryptedEmailsForLookup(email);
    for (let i = 0; i < variants.length; i++) {
      if (Object.prototype.hasOwnProperty.call(memberIndex, variants[i])) {
        memberId = memberIndex[variants[i]];
        break;
      }
    }
  } catch (error) {
    memberId = '';
  }
  writerMemo[encryptedEmail] = memberId;
  return memberId;
}

/**
 * 사용자 정보 가져오기 (이메일로)
 * @param {string} email - 사용자 이메일
 * @returns {Object} 사용자 정보
 */
function getUserByEmail(email) {
  try {
    const spreadsheet = getHpMemberSpreadsheet();
    if (!spreadsheet) {
      return null;
    }
    
    const sheetName = getUserSheetName();
    const data = getSheetData(spreadsheet.getId(), sheetName, 'A:G');
    
    if (!data || data.length <= 1) {
      return null;
    }
    
    const header = data[0];
    const encryptedVariants = getEncryptedEmailsForLookup(email);
    
    for (let i = 1; i < data.length; i++) {
      const row = data[i];
      const user = {};
      header.forEach((key, index) => {
        user[key] = row[index];
      });
      
      if (encryptedVariants.includes(user.google_member) && isApprovedUser_(user)) {
        return {
          no_member: user.no_member,
          user_type: user.user_type,
          name_member: user.name_member,
          email: email,
          is_admin: user.is_admin === 'O'
        };
      }
    }
    
    return null;
  } catch (error) {
    logError_('AnnouncementManagement', '사용자 정보 가져오기 오류:', error);
    return null;
  }
}

/**
 * 사용자 정보 가져오기 (학번/교번 no_member)
 * @param {string} memberId
 * @returns {Object|null}
 */
function getUserByMemberId(memberId) {
  try {
    const targetId = String(memberId || '').trim();
    if (!targetId) return null;

    const spreadsheet = getHpMemberSpreadsheet();
    if (!spreadsheet) return null;

    const sheetName = getUserSheetName();
    const data = getSheetData(spreadsheet.getId(), sheetName, 'A:G');
    if (!data || data.length <= 1) return null;

    const header = data[0];
    for (let i = 1; i < data.length; i++) {
      const row = data[i];
      const user = {};
      header.forEach((key, index) => {
        user[key] = row[index];
      });

      if (String(user.no_member || '').trim() === targetId && isApprovedUser_(user)) {
        let decrypted = '';
        try {
          decrypted = user.google_member ? decryptEmailMain(user.google_member) : '';
        } catch (e) {
          decrypted = '';
        }
        return {
          no_member: user.no_member,
          user_type: user.user_type,
          name_member: user.name_member,
          email: decrypted,
          is_admin: user.is_admin === 'O'
        };
      }
    }
    return null;
  } catch (error) {
    logError_('AnnouncementManagement', '학번 기반 사용자 조회 오류:', error);
    return null;
  }
}

/**
 * 사용자 목록 가져오기 (권한 설정용)
 * @returns {Array} 사용자 목록
 */
function getUserList() {
  try {
    const spreadsheet = getHpMemberSpreadsheet();
    if (!spreadsheet) {
      return [];
    }
    
    const sheetName = getUserSheetName();
    const data = getSheetData(spreadsheet.getId(), sheetName, 'A:G');
    
    if (!data || data.length <= 1) {
      return [];
    }
    
    const header = data[0];
    const users = [];
    
    for (let i = 1; i < data.length; i++) {
      const row = data[i];
      const user = {};
      header.forEach((key, index) => {
        user[key] = row[index];
      });
      
      if (user.no_member && user.name_member && isApprovedUser_(user)) {
        users.push({
          id: user.no_member,
          name: user.name_member,
          user_type: user.user_type || 'student',
          email: user.google_member ? decryptEmailMain(user.google_member) : ''
        });
      }
    }
    
    return users;
  } catch (error) {
    logError_('AnnouncementManagement', '사용자 목록 가져오기 오류:', error);
