}

/**
 * 공지사항 작성 권한 확인
 * @param {string} userType - 사용자 타입
 * @returns {boolean} 작성 권한 여부
 */
function canCreateAnnouncement(userType) {
  // student는 작성 불가, 나머지는 모두 가능
  return userType !== 'student';
}

/**
 * 공지사항 수정 권한 확인
 * @param {string} writerId - 작성자 ID
 * @param {string} currentUserId - 현재 사용자 ID
 * @returns {boolean} 수정 권한 여부
 */
function canEditAnnouncement(writerId, currentUserId) {
  return String(writerId) === String(currentUserId);
}

/**
 * 공지사항 읽기 권한 확인
 * @param {Object} announcement - 공지사항 정보
 * @param {string} userId - 사용자 ID
 * @param {string} userType - 사용자 타입
 * @returns {boolean} 읽기 권한 여부
 */
function canReadAnnouncement(announcement, userId, userType) {
  const writerIdStr = String(announcement.writer_id || '');
  const userIdStr = String(userId || '');
  
  // 작성자는 항상 읽기 가능
  if (writerIdStr && writerIdStr !== '' && writerIdStr === userIdStr) {
    return true;
  }
  
  // 권한 설정이 없으면 전체 사용자 대상 공지 (모든 승인된 사용자가 볼 수 있음)
  if (!announcement.access_rights || announcement.access_rights === '' || announcement.access_rights.trim() === '') {
    return true;
  }
  
  try {
    const accessRights = JSON.parse(announcement.access_rights);
    
    // 개별 권한 확인 (ID를 문자열로 통일하여 비교)
    if (accessRights.individual && Array.isArray(accessRights.individual)) {
      const hasAccess = accessRights.individual.some(id => {
        const idStr = String(id);
        const match = idStr === userIdStr;
        return match;
      });
      if (hasAccess) {
        return true;
      }
    }
    
    // 그룹 권한 확인
    if (accessRights.groups && Array.isArray(accessRights.groups)) {
      if (accessRights.groups.includes(userType)) {
        return true;
      }
    }
    return false;
  } catch (error) {
    return false;
  }
}

/**
 * 공지사항 목록 가져오기 (권한 필터링)
 * @param {string} spreadsheetName - 스프레드시트 이름
 * @param {string} userId - 사용자 ID
 * @param {string} userType - 사용자 타입
 * @returns {Object} 공지사항 목록
 */
function getAnnouncements(req) {
  try {
    const { spreadsheetName, spreadsheetId, userId, userType } = req;
    
    if (!hasAnnouncementSheetRef_(req) || !userId || !userType) {
      return {
        success: false,
        message: '필수 파라미터가 누락되었습니다.',
        announcements: []
      };
    }
    
    const spreadsheet = openAnnouncementSpreadsheetFromRequest_(req);
    const sheet = resolveNoticeSheet_(spreadsheet, req);

    if (!sheet) {
      return {
        success: false,
        message: '공지 스프레드시트에서 데이터 탭을 찾을 수 없습니다. (.env 시트명 또는 NOTICE_SHEET_NAME)',
        announcements: [],
        debug: { availableSheets: spreadsheet.getSheets().map(function (s) { return s.getName(); }) }
      };
    }

    const data = sheet.getDataRange().getValues();
    if (!data || data.length <= 1) {
      return {
        success: true,
        announcements: [],
        message: '공지사항이 없습니다.'
      };
    }
    
    const header = data[0];
    const announcements = [];
    const memberIndex = buildApprovedMemberIndex_();
    const writerMemo = {};
    
    // 헤더 인덱스 찾기
    const headerMap = {};
    header.forEach((h, index) => {
      headerMap[h] = index;
    });
    
    for (let i = 1; i < data.length; i++) {
      const row = data[i];
      
      // no_notice가 비어있으면 건너뛰기
      const noticeId = row[headerMap['no_notice']];
      if (!noticeId || noticeId === '') {
        continue;
      }
      
      const announcement = {
        id: String(noticeId), // ID를 문자열로 통일
        writer_notice: row[headerMap['writer_notice']] || '',
        writer_email: row[headerMap['writer_email']] || '',
        writer_id: '', // writer_email에서 추출 필요
        access_rights: row[headerMap['access_rights']] || '',
        title_notice: row[headerMap['title_notice']] || '',
        content_notice: row[headerMap['content_notice']] || '',
        date: row[headerMap['date']] || '',
        view_count: parseInt(row[headerMap['view_count']] || '0', 10),
        file_notice: row[headerMap['file_notice']] || '',
        fix_notice: row[headerMap['fix_notice']] || ''
      };
      
      // writer_email에서 writer_id 추출 (암호화된 이메일에서 사용자 찾기)
      const writerId = resolveApprovedMemberId_(announcement.writer_email, memberIndex, writerMemo);
      announcement.writer_id = writerId === '' ? '' : String(writerId);
      
      // 권한 확인
      const canRead = canReadAnnouncement(announcement, String(userId), userType);
      
      if (canRead) {
        announcements.push(announcement);
      } else {
      }
    }
    
    // 고정 공지 분리 및 정렬
    const pinnedAnnouncements = announcements.filter(a => a.fix_notice === 'O');
    const normalAnnouncements = announcements.filter(a => a.fix_notice !== 'O');
    
    // 고정 공지와 일반 공지를 각각 ID 역순으로 정렬 (최신순)
    pinnedAnnouncements.sort((a, b) => parseInt(b.id, 10) - parseInt(a.id, 10));
    normalAnnouncements.sort((a, b) => parseInt(b.id, 10) - parseInt(a.id, 10));
    
    const sortedAnnouncements = [...pinnedAnnouncements, ...normalAnnouncements];
    
    return {
      success: true,
      announcements: sortedAnnouncements,
      message: `${sortedAnnouncements.length}개의 공지사항을 불러왔습니다.`
    };
  } catch (error) {
    logError_('AnnouncementManagement', '공지사항 목록 가져오기 오류:', error);
    return {
      success: false,
      message: '공지사항 목록을 가져오는 중 오류가 발생했습니다: ' + error.message,
      announcements: []
    };
  }
}

/**
 * 공지사항 본문의 Base64 인코딩 이미지를 Google Drive에 업로드하고 URL로 대체
 * @param {string} content - HTML 콘텐츠
 * @returns {string} 처리된 HTML 콘텐츠
 */
/**
 * 공지 첨부·본문 이미지 폴더 (ROOT/notice/attached_file, 없으면 만든다)
 */
function getNoticeAttachFolder_() {
  const props = PropertiesService.getScriptProperties();
  const rootId = getProjectRootFolderId_();
  if (!rootId) throw new Error('루트 폴더를 찾을 수 없습니다.');
  const getOrCreateChild = function(parent, name) {
    const found = parent.getFoldersByName(name);
    return found.hasNext() ? found.next() : parent.createFolder(name);
  };
  const notice = getOrCreateChild(DriveApp.getFolderById(rootId), props.getProperty('NOTICE_ATTACH_PARENT_FOLDER_NAME') || 'notice');
  return getOrCreateChild(notice, props.getProperty('NOTICE_ATTACH_FOLDER_NAME') || 'attached_file');
}

/**
 * 공지 첨부파일 업로드 (프론트가 base64로 보낸 파일을 배포자 드라이브의 첨부 폴더에 저장)
 * @param {Object} req - { fileName, mimeType, fileData(base64) }
 */
function uploadNoticeAttachment(req) {
  try {
    if (!req.fileName || !req.fileData) {
      return { success: false, message: '파일 이름과 내용이 필요합니다.' };
    }
    const blob = Utilities.newBlob(Utilities.base64Decode(req.fileData), req.mimeType || 'application/octet-stream', req.fileName);
    const file = getNoticeAttachFolder_().createFile(blob);
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
    return { success: true, data: { id: file.getId(), name: req.fileName, url: file.getUrl() } };
  } catch (error) {
    logError_('AnnouncementManagement', '공지 첨부파일 업로드 오류:', error);
    return { success: false, message: '첨부파일 업로드 중 오류가 발생했습니다: ' + error.message };
  }
}

function processAndUploadImages_(content) {
  if (!content || content.indexOf('data:image/') === -1) return content;

  let targetFolder;
  try {
    targetFolder = getNoticeAttachFolder_();
  } catch (folderError) {
    logWarn_('AnnouncementManagement', '공지 본문 이미지 폴더를 찾지 못해 드라이브 루트에 저장합니다:', folderError);
    targetFolder = DriveApp.getRootFolder();
  }
  const imgRegex = /<img src="(data:image\/([^;]+);base64,([^"]+))"[^>]*>/g;
  
  let processedContent = content;
  let match;
  
  while ((match = imgRegex.exec(content)) !== null) {
    const fullDataUrl = match[1];
    const mimeSubType = match[2];
    const mimeType = `image/${mimeSubType}`;
    const base64Data = match[3];
    
    try {
      const decodedData = Utilities.base64Decode(base64Data);
      const extension = mimeSubType === 'jpeg' ? 'jpg' : mimeSubType;
      const blob = Utilities.newBlob(decodedData, mimeType, `announcement-image-${Date.now()}.${extension}`);
      
      const file = targetFolder.createFile(blob);
      
      // 파일을 공개적으로 접근 가능하도록 설정
      file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
      
      // 안정적인 이미지 URL 생성
      const fileId = file.getId();
      const imageUrl = `https://drive.google.com/uc?export=view&id=${fileId}`;
      
      // 원본 Base64 URL을 새로 생성된 URL로 교체
      processedContent = processedContent.replace(fullDataUrl, imageUrl);
      
    } catch (e) {
      logError_('AnnouncementManagement', '이미지 처리 중 오류 발생:', e);
      // 오류가 발생해도 계속 진행 (해당 이미지는 업로드되지 않음)
    }
  }
  
  return processedContent;
}


/**
 * 공지사항 작성
 * @param {Object} req - 요청 데이터
 * @returns {Object} 작성 결과
 */
function createAnnouncementUnlocked_(req) {
  try {
    const { 
      spreadsheetName, 
      spreadsheetId,
      writerEmail, 
      writerId,
      writerName, 
      userType,
      title, 
      content, 
      fileNotice, 
      accessRights, 
      isPinned 
    } = req;
    
    if (!hasAnnouncementSheetRef_(req) || !writerEmail || !title || !content) {
      return {
        success: false,
        message: '필수 파라미터가 누락되었습니다.'
      };
    }
    
    // 사용자 정보 확인 (이메일 우선, 실패 시 학번 fallback)
    let user = getUserByEmail(writerEmail);
    if (!user && writerId) {
      user = getUserByMemberId(writerId);
    }
    if (!user) {
      return {
        success: false,
        message: '사용자 정보를 찾을 수 없습니다.'
      };
    }
    
    // 작성 권한 확인
    const effectiveUserType = String(user.user_type || userType || '').trim();
    if (!canCreateAnnouncement(effectiveUserType)) {
      return {
        success: false,
        message: '학생은 공지사항을 작성할 수 없습니다.'
      };
    }
    
    const spreadsheet = openAnnouncementSpreadsheetFromRequest_(req);
    const sheet = resolveNoticeSheet_(spreadsheet, req);

    if (!sheet) {
      return {
        success: false,
        message: '공지 스프레드시트에서 데이터 탭을 찾을 수 없습니다. (.env 시트명 또는 NOTICE_SHEET_NAME)'
      };
    }

    // 새 공지 번호 생성 (기존 최대값 + 1)
    const data = sheet.getDataRange().getValues();
    let maxId = 0;
    if (data.length > 1) {
      const ids = data.slice(1) // 헤더 제외
        .map(row => parseInt(row[0], 10)) // 첫 번째 열(no_notice)을 숫자로 변환
        .filter(id => !isNaN(id) && id > 0); // 유효한 숫자 ID만 필터링
      
      if (ids.length > 0) {
        maxId = Math.max(...ids);
      } else {
        maxId = 0; // 유효한 ID가 없으면 0부터 시작
      }
    }
    const newNoticeId = maxId + 1;

    // 이미지 처리
    const processedContent = processAndUploadImages_(content);
    
    // 이메일 암호화 (CONFIG 기반 다중 레이어)
    const encryptedEmail = encryptEmailMain(writerEmail);
    
    // 권한 설정 JSON 문자열화
    const accessRightsStr = accessRights ? JSON.stringify(accessRights) : '';
    
    // 고정 공지 상태 (요청 시 '-', 아니면 빈칸)
    const fixNotice = isPinned ? '-' : '';
    
    // 새 행 추가
    const newRow = [
      newNoticeId,              // A: no_notice
      writerName || user.name_member, // B: writer_notice
      encryptedEmail,           // C: writer_email
      accessRightsStr,          // D: access_rights
      title,                     // E: title_notice
      processedContent,          // F: content_notice
      new Date().toISOString().slice(0, 10), // G: date
      0,                         // H: view_count
      fileNotice || '',          // I: file_notice
      fixNotice                  // J: fix_notice
    ];
    
    sheet.appendRow(newRow);
    
    return {
      success: true,
      message: '공지사항이 작성되었습니다.',
      announcementId: newNoticeId
    };
  } catch (error) {
    logError_('AnnouncementManagement', '공지사항 작성 오류:', error);
    return {
      success: false,
      message: '공지사항 작성 중 오류가 발생했습니다: ' + error.message
    };
  }
}

/**
 * 공지사항 수정
 * @param {Object} req - 요청 데이터
 * @returns {Object} 수정 결과
 */
function updateAnnouncement(req) {
  try {
    const { 
      spreadsheetName, 
      spreadsheetId,
      announcementId, 
      userId, 
      title, 
      content, 
      fileNotice, 
      accessRights,
      isPinned 
    } = req;
    
    if (!hasAnnouncementSheetRef_(req) || !announcementId || !userId) {
      return {
        success: false,
        message: '필수 파라미터가 누락되었습니다.'
      };
    }
    
    const spreadsheet = openAnnouncementSpreadsheetFromRequest_(req);
    const sheet = resolveNoticeSheet_(spreadsheet, req);

    if (!sheet) {
      return {
        success: false,
        message: '공지 스프레드시트에서 데이터 탭을 찾을 수 없습니다. (.env 시트명 또는 NOTICE_SHEET_NAME)'
      };
    }

    const data = sheet.getDataRange().getValues();
    if (!data || data.length <= 1) {
      return {
        success: false,
        message: '공지사항 데이터를 찾을 수 없습니다.'
      };
    }

    const header = data[0];
    const headerMap = {};
    header.forEach((h, index) => {
      headerMap[h] = index;
    });
    const memberIndex = buildApprovedMemberIndex_();
    const writerMemo = {};

    // 공지사항 찾기
    let targetRowIndex = -1;
    let announcement = null;
    
    for (let i = 1; i < data.length; i++) {
      const row = data[i];
      if (String(row[headerMap['no_notice']]) === String(announcementId)) {
        targetRowIndex = i + 1; // 시트 행 번호 (1-based)
        announcement = {
          writer_id: resolveApprovedMemberId_(row[headerMap['writer_email']], memberIndex, writerMemo)
        };
        break;
      }
    }
    
    if (targetRowIndex === -1 || !announcement) {
      return {
        success: false,
        message: '공지사항을 찾을 수 없습니다.'
      };
    }
    
    // 수정 권한 확인
    if (!canEditAnnouncement(announcement.writer_id, userId)) {
      return {
        success: false,
        message: '수정 권한이 없습니다.'
      };
    }
    
    // 현재 fix_notice 값 확인 (targetRowIndex를 사용하여 데이터에서 가져오기)
    const currentRow = data[targetRowIndex - 1]; // targetRowIndex는 1-based이므로 -1
    const currentFixNotice = currentRow[headerMap['fix_notice']] || '';
    
    // 수정할 데이터 준비
    const updateData = {};
    if (title !== undefined) updateData[headerMap['title_notice']] = title;
    if (content !== undefined) updateData[headerMap['content_notice']] = processAndUploadImages_(content);
    if (fileNotice !== undefined) updateData[headerMap['file_notice']] = fileNotice;
    if (accessRights !== undefined) {
      updateData[headerMap['access_rights']] = accessRights ? JSON.stringify(accessRights) : '';
    }
    
    // 고정 공지 처리
    if (isPinned !== undefined) {
      if (isPinned) {
        // 고정 공지 요청: 기존에 'O'가 아니면 '-'로 설정 (요청)
        if (currentFixNotice !== 'O') {
          updateData[headerMap['fix_notice']] = '-';
        }
        // 이미 'O'면 그대로 유지
      } else {
        // 고정 공지 해제: 'O'인 경우에만 빈칸으로 변경 (요청 중이거나 거절된 경우는 유지)
        if (currentFixNotice === 'O') {
          updateData[headerMap['fix_notice']] = '';
        }
      }
    }
    
    // 데이터 업데이트
    Object.keys(updateData).forEach(colIndex => {
      sheet.getRange(targetRowIndex, parseInt(colIndex) + 1).setValue(updateData[colIndex]);
    });
    
    return {
      success: true,
      message: '공지사항이 수정되었습니다.'
    };
  } catch (error) {
    logError_('AnnouncementManagement', '공지사항 수정 오류:', error);
    return {
      success: false,
      message: '공지사항 수정 중 오류가 발생했습니다: ' + error.message
    };
  }
}

/**
 * 공지사항 삭제
 * @param {Object} req - 요청 데이터
 * @returns {Object} 삭제 결과
 */
function deleteAnnouncement(req) {
  try {
    const { spreadsheetName, spreadsheetId, announcementId, userId } = req;
    
    if (!hasAnnouncementSheetRef_(req) || !announcementId || !userId) {
      return {
        success: false,
        message: '필수 파라미터가 누락되었습니다.'
      };
    }
    
    const spreadsheet = openAnnouncementSpreadsheetFromRequest_(req);
    const sheet = resolveNoticeSheet_(spreadsheet, req);
    
    if (!sheet) {
      return {
        success: false,
        message: '공지 스프레드시트에서 데이터 탭을 찾을 수 없습니다. (.env 시트명 또는 NOTICE_SHEET_NAME)'
      };
    }
    
    const data = sheet.getDataRange().getValues();
    if (!data || data.length <= 1) {
      return {
        success: false,
        message: '공지사항 데이터를 찾을 수 없습니다.'
      };
    }
    
    const header = data[0];
    const headerMap = {};
    header.forEach((h, index) => {
      headerMap[h] = index;
    });
    const memberIndex = buildApprovedMemberIndex_();
    const writerMemo = {};
    
    // 공지사항 찾기 및 권한 확인
    let targetRowIndex = -1;
    for (let i = 1; i < data.length; i++) {
      const row = data[i];
      const noticeId = row[headerMap['no_notice']];
      
      // no_notice가 비어있으면 건너뛰기
      if (!noticeId || noticeId === '') {
        continue;
      }
      
      if (String(noticeId) === String(announcementId)) {
        const writerEmail = row[headerMap['writer_email']];
        const writerId = resolveApprovedMemberId_(writerEmail, memberIndex, writerMemo);
        
        if (writerId === '' || !canEditAnnouncement(writerId, userId)) {
          return {
            success: false,
            message: '삭제 권한이 없습니다.'
          };
        }
        
        targetRowIndex = i + 1; // 시트 행 번호 (1-based)
        break;
      }
    }
    
    if (targetRowIndex === -1) {
      return {
        success: false,
        message: '공지사항을 찾을 수 없습니다.'
      };
    }
    
    // 행 삭제
    sheet.deleteRow(targetRowIndex);
    
    // 삭제 후 남은 공지사항들의 no_notice 번호를 행 번호로 재정렬
    const updatedData = sheet.getDataRange().getValues();
    if (updatedData && updatedData.length > 1) {
      const noNoticeColIndex = headerMap['no_notice'];
      if (noNoticeColIndex !== undefined && noNoticeColIndex !== null) {
        // 헤더를 제외한 실제 데이터가 있는 행들만 번호 매기기
        let noticeNumber = 1; // 실제 데이터 행 번호 (1부터 시작)
        let numberChanged = false;
        
        for (let i = 1; i < updatedData.length; i++) {
          const row = updatedData[i];
          const currentNoticeId = row[noNoticeColIndex];
          
          // no_notice가 비어있거나 빈 행이면 건너뛰기
          if (!currentNoticeId || currentNoticeId === '') {
            continue;
          }
          
          // 현재 값이 행 번호와 다르면 업데이트
          if (String(currentNoticeId) !== String(noticeNumber)) {
            row[noNoticeColIndex] = noticeNumber;
            numberChanged = true;
          }
          
          noticeNumber++; // 다음 번호로 증가
        }
        
        if (numberChanged) {
          sheet.getRange(2, noNoticeColIndex + 1, updatedData.length - 1, 1)
            .setValues(updatedData.slice(1).map(row => [row[noNoticeColIndex]]));
          SpreadsheetApp.flush();
        }
      }
    }
    
    return {
      success: true,
      message: '공지사항이 삭제되었고 번호가 재정렬되었습니다.'
    };
  } catch (error) {
    logError_('AnnouncementManagement', '공지사항 삭제 오류:', error);
    return {
      success: false,
      message: '공지사항 삭제 중 오류가 발생했습니다: ' + error.message
    };
  }
}

