/**
 * 고정 공지 승인/거절 (관리자용)
 * @param {Object} req - 요청 데이터
 * @returns {Object} 결과
 */
function approvePinnedAnnouncement(req) {
  try {
    // approvalAction을 사용 (action은 라우팅용으로 사용되므로)
    const { spreadsheetName, spreadsheetId, announcementId, approvalAction } = req;
    const action = approvalAction; // 'approve' or 'reject'
    
    if (!hasAnnouncementSheetRef_(req) || !announcementId || !action) {
      return {
        success: false,
        message: '필수 파라미터가 누락되었습니다.',
        debug: { spreadsheetName, spreadsheetId, announcementId, approvalAction, action }
      };
    }
    
    if (action !== 'approve' && action !== 'reject') {
      return {
        success: false,
        message: '잘못된 액션입니다. (approve 또는 reject만 가능)',
        debug: { action }
      };
    }
    
    const spreadsheet = openAnnouncementSpreadsheetFromRequest_(req);
    const sheet = resolveNoticeSheet_(spreadsheet, req);

    if (!sheet) {
      return {
        success: false,
        message: '공지 스프레드시트에서 데이터 탭을 찾을 수 없습니다. (.env 시트명 또는 NOTICE_SHEET_NAME)',
        debug: {
          spreadsheetName,
          spreadsheetId,
          availableSheets: spreadsheet.getSheets().map(s => s.getName())
        }
      };
    }

    const data = sheet.getDataRange().getValues();
    if (!data || data.length <= 1) {
      return {
        success: false,
        message: '공지사항 데이터를 찾을 수 없습니다.'
      };
    }

    const header = data[0];
    const headerMap = {};
    header.forEach((h, index) => {
      headerMap[h] = index;
    });

    // 공지사항 찾기
    let targetRowIndex = -1;
    for (let i = 1; i < data.length; i++) {
      const row = data[i];
      const noticeId = row[headerMap['no_notice']];

      // no_notice가 비어있으면 건너뛰기
      if (!noticeId || noticeId === '') {
        continue;
      }

      if (String(noticeId) === String(announcementId)) {
        targetRowIndex = i + 1; // 시트 행 번호 (1-based)
        break;
      }
    }

    if (targetRowIndex === -1) {
      // 디버깅: 찾은 공지사항 ID 목록
      const foundIds = [];
      for (let i = 1; i < Math.min(data.length, 10); i++) {
        const row = data[i];
        const noticeId = row[headerMap['no_notice']];
        if (noticeId) {
          foundIds.push(String(noticeId));
        }
      }
      return {
        success: false,
        message: '공지사항을 찾을 수 없습니다.',
        debug: { 
          requestedId: String(announcementId), 
          foundIds: foundIds,
          totalRows: data.length - 1
        }
      };
    }
    
    // fix_notice 컬럼 확인
    const fixNoticeColIndex = headerMap['fix_notice'];
    if (fixNoticeColIndex === undefined || fixNoticeColIndex === null) {
      return {
        success: false,
        message: 'fix_notice 컬럼을 찾을 수 없습니다. 헤더: ' + JSON.stringify(header)
      };
    }
    
    // 고정 공지 상태 업데이트
    const fixNoticeValue = action === 'approve' ? 'O' : 'X';
    
    try {
      // 시트 업데이트
      const targetRange = sheet.getRange(targetRowIndex, fixNoticeColIndex + 1);
      targetRange.setValue(fixNoticeValue);
      
      // 변경사항 즉시 반영
      SpreadsheetApp.flush();
      
      // 업데이트 확인
      const updatedValue = targetRange.getValue();
      if (updatedValue !== fixNoticeValue) {
        return {
          success: false,
          message: '시트 업데이트가 실패했습니다. 예상값: ' + fixNoticeValue + ', 실제값: ' + updatedValue
        };
      }
      
      return {
        success: true,
        message: action === 'approve' ? '고정 공지가 승인되었습니다.' : '고정 공지가 거절되었습니다.',
        updatedValue: updatedValue
      };
    } catch (updateError) {
      return {
        success: false,
        message: '시트 업데이트 중 오류가 발생했습니다: ' + updateError.message
      };
    }
  } catch (error) {
    logError_('AnnouncementManagement', '고정 공지 승인/거절 오류:', error);
    return {
      success: false,
      message: '고정 공지 승인/거절 중 오류가 발생했습니다: ' + error.message
    };
  }
}

/**
 * 고정 공지 승인 대기 목록 가져오기 (관리자용)
 * @param {Object} req - 요청 데이터
 * @returns {Object} 승인 대기 목록
 */
function getPinnedAnnouncementRequests(req) {
  try {
    const { spreadsheetName, spreadsheetId } = req;
    
    if (!hasAnnouncementSheetRef_(req)) {
      return {
        success: false,
        message: '필수 파라미터가 누락되었습니다.',
        requests: []
      };
    }
    
    const spreadsheet = openAnnouncementSpreadsheetFromRequest_(req);
    const sheet = resolveNoticeSheet_(spreadsheet, req);

    if (!sheet) {
      return {
        success: false,
        message: '공지 스프레드시트에서 데이터 탭을 찾을 수 없습니다. (.env 시트명 또는 NOTICE_SHEET_NAME)',
        requests: []
      };
    }

    const data = sheet.getDataRange().getValues();
    if (!data || data.length <= 1) {
      return {
        success: true,
        requests: [],
        message: '승인 대기 중인 고정 공지가 없습니다.'
      };
    }

    const header = data[0];
    const headerMap = {};
    header.forEach((h, index) => {
      headerMap[h] = index;
    });
    const memberIndex = buildApprovedMemberIndex_();
    const writerMemo = {};
    
    const requests = [];
    
    for (let i = 1; i < data.length; i++) {
      const row = data[i];
      const fixNotice = row[headerMap['fix_notice']] || '';
      
      // 승인 대기 중인 것만 ('-')
      if (fixNotice === '-') {
        const writerEmail = row[headerMap['writer_email']];
        const decryptedEmail = decryptEmailMain(writerEmail);
        const writerId = resolveApprovedMemberId_(writerEmail, memberIndex, writerMemo, decryptedEmail);
        
        requests.push({
          id: row[headerMap['no_notice']] || '',
          title: row[headerMap['title_notice']] || '',
          writer: row[headerMap['writer_notice']] || '',
          writerEmail: decryptedEmail,
          writerId: writerId,
          date: row[headerMap['date']] || '',
          status: 'pending'
        });
      }
    }
    
    return {
      success: true,
      requests: requests,
      message: `${requests.length}개의 승인 대기 중인 고정 공지가 있습니다.`
    };
  } catch (error) {
    logError_('AnnouncementManagement', '고정 공지 승인 대기 목록 가져오기 오류:', error);
    return {
      success: false,
      message: '고정 공지 승인 대기 목록을 가져오는 중 오류가 발생했습니다: ' + error.message,
      requests: []
    };
  }
}

