    // 설정 검증
    function validateConfig() {
    const errors = [];
    
    // 스프레드시트 ID 확인 (스크립트 속성 SPREADSHEET_ID 필수)
    const spreadsheetId = getSpreadsheetId();
    if (!spreadsheetId) {
        errors.push('스크립트 속성 SPREADSHEET_ID가 설정되지 않았습니다. (프로젝트 설정 > 스크립트 속성)');
    }
    
    // 암호화 방법 확인
    if (!ENCRYPTION_METHODS || ENCRYPTION_METHODS.length === 0) {
        errors.push('암호화 방법이 정의되지 않았습니다.');
    }
    
    // 레이어 설정 확인
    if (LAYER_CONFIG.MIN_LAYERS >= LAYER_CONFIG.MAX_LAYERS) {
        errors.push('레이어 설정이 잘못되었습니다.');
    }
    
    return {
        isValid: errors.length === 0,
        errors: errors
    };
    }

