/**
 * EncryptionKeyManagement.gs
 * 암호화 키 관리 관련 함수들
 * Hot Potato Admin Key Management System
 */

// ===== 키 생성 및 관리 함수들 =====

/**
 * 확장된 다중 레이어 키 생성
 * @returns {Object} 생성된 키 정보
 */
function generateExtendedMultiLayerKey() {
  try {
    
    // CONFIG에서 암호화 방법들 가져오기
    const methods = getConfig('encryption_methods');
    const layerConfig = getConfig('layer_config');
    
    const layerCount = Math.floor(Math.random() * (layerConfig.MAX_LAYERS - layerConfig.MIN_LAYERS + 1)) + layerConfig.MIN_LAYERS;
    const selectedMethods = [];
    
    for (let i = 0; i < layerCount; i++) {
      const randomIndex = Math.floor(Math.random() * methods.length);
      selectedMethods.push(methods[randomIndex]);
    }
    
    // 안전한 랜덤 문자열 생성
    const randomPart1 = Math.random().toString(36).substring(2);
    const randomPart2 = Math.random().toString(36).substring(2);
    const randomPart = randomPart1 + randomPart2;
    const dateStr = new Date().toISOString().split('T')[0];
    const baseKey = `ADMIN_${dateStr}_${randomPart.substring(0, 13)}`;
    
    let encryptedKey = baseKey;
    for (let i = 0; i < selectedMethods.length; i++) {
      const method = selectedMethods[i];
      const beforeEncrypt = encryptedKey;
      encryptedKey = applyEncryption(encryptedKey, method, '');
      
      if (!encryptedKey || encryptedKey === 'undefined' || encryptedKey.includes('undefined')) {
        logError_('EncryptionKeyManagement', `암호화 실패: ${method}에서 undefined 반환`);
        throw new Error(`암호화 실패: ${method}에서 undefined 반환`);
      }
    }
    
    return {
      key: encryptedKey,
      layers: selectedMethods,
      originalKey: baseKey
    };
  } catch (error) {
    logError_('EncryptionKeyManagement', '관리자 키 생성 오류');
    throw error;
  }
}

/**
 * 키 검증
 * @param {string} encryptedKey - 암호화된 키
 * @param {Array} methods - 암호화 방법 배열
 * @returns {Object} 검증 결과
 */
function validateEncryptedKey(encryptedKey, methods) {
  try {
    
    // 역순으로 복호화
    let decryptedKey = encryptedKey;
    for (let i = methods.length - 1; i >= 0; i--) {
      const method = methods[i];
      const beforeDecrypt = decryptedKey;
      decryptedKey = applyDecryption(decryptedKey, method, '');
    }
    
    // 키 형식 검증
    const isValidFormat = decryptedKey.startsWith('ADMIN_') && decryptedKey.includes('_');
    
    return {
      success: isValidFormat,
      decryptedKey: decryptedKey,
      isValidFormat: isValidFormat,
      message: isValidFormat ? '키가 유효합니다' : '키 형식이 올바르지 않습니다'
    };
    
  } catch (error) {
    logError_('EncryptionKeyManagement', '키 검증 오류');
    return {
      success: false,
      error: error.message,
      message: '키 검증 중 오류가 발생했습니다'
    };
  }
}

/**
 * 키 복호화
 * @param {string} encryptedKey - 암호화된 키
 * @param {Array} methods - 암호화 방법 배열
 * @returns {string} 복호화된 키
 */
function decryptKey(encryptedKey, methods) {
  try {
    
    let decryptedKey = encryptedKey;
    for (let i = methods.length - 1; i >= 0; i--) {
      const method = methods[i];
      decryptedKey = applyDecryption(decryptedKey, method, '');
    }
    return decryptedKey;
    
  } catch (error) {
    logError_('EncryptionKeyManagement', '키 복호화 오류');
    throw error;
  }
}

/**
 * 키 재암호화
 * @param {string} originalKey - 원본 키
 * @param {Array} newMethods - 새로운 암호화 방법 배열
 * @returns {Object} 재암호화된 키 정보
 */
function reencryptKey(originalKey, newMethods) {
  try {
    
    let encryptedKey = originalKey;
    for (let i = 0; i < newMethods.length; i++) {
      const method = newMethods[i];
      encryptedKey = applyEncryption(encryptedKey, method, '');
    }
    
    return {
      success: true,
      key: encryptedKey,
      layers: newMethods,
      originalKey: originalKey
    };
    
  } catch (error) {
    logError_('EncryptionKeyManagement', '키 재암호화 오류');
    return {
      success: false,
      error: error.message
    };
  }
}

/**
 * 키 강도 분석
 * @param {string} encryptedKey - 암호화된 키
 * @param {Array} methods - 암호화 방법 배열
 * @returns {Object} 키 강도 분석 결과
 */
function analyzeKeyStrength(encryptedKey, methods) {
  try {
    
    const analysis = {
      keyLength: encryptedKey.length,
      layerCount: methods.length,
      methods: methods,
      complexity: 0,
      strength: 'weak'
    };
    
    // 복잡도 계산
    analysis.complexity = methods.length * 10;
    
    // 키 길이에 따른 보너스
    if (encryptedKey.length > 50) {
      analysis.complexity += 20;
    } else if (encryptedKey.length > 30) {
      analysis.complexity += 10;
    }
    
    // 강도 평가
    if (analysis.complexity >= 80) {
      analysis.strength = 'very_strong';
    } else if (analysis.complexity >= 60) {
      analysis.strength = 'strong';
    } else if (analysis.complexity >= 40) {
      analysis.strength = 'medium';
    } else {
      analysis.strength = 'weak';
    }
    
    return {
      success: true,
      analysis: analysis
    };
    
  } catch (error) {
    logError_('EncryptionKeyManagement', '키 강도 분석 오류');
    return {
      success: false,
      error: error.message
    };
  }
}

/**
 * 키 백업 생성
 * @param {string} encryptedKey - 암호화된 키
 * @param {Array} methods - 암호화 방법 배열
 * @returns {Object} 백업 정보
 */
function createKeyBackup(encryptedKey, methods) {
  try {
    
    const backup = {
      encryptedKey: encryptedKey,
      methods: methods,
      timestamp: new Date().toISOString(),
      version: '1.0.0'
    };
    
    return {
      success: true,
      backup: backup,
      message: '키 백업이 생성되었습니다'
    };
    
  } catch (error) {
    logError_('EncryptionKeyManagement', '키 백업 생성 오류');
    return {
      success: false,
      error: error.message
    };
  }
}

/**
 * 키 백업 복원
 * @param {Object} backup - 백업 정보
 * @returns {Object} 복원 결과
 */
function restoreKeyBackup(backup) {
  try {
    
    if (!backup.encryptedKey || !backup.methods) {
      return {
        success: false,
        message: '백업 정보가 올바르지 않습니다'
      };
    }
    
    // 키 검증
    const validation = validateEncryptedKey(backup.encryptedKey, backup.methods);
    
    return {
      success: validation.success,
      key: backup.encryptedKey,
      methods: backup.methods,
      validation: validation
    };
    
  } catch (error) {
    logError_('EncryptionKeyManagement', '키 백업 복원 오류');
    return {
      success: false,
      error: error.message
    };
  }
}

// ===== 배포 정보 =====
function getEncryptionKeyManagementInfo() {
  return {
    version: '1.0.0',
    description: '암호화 키 관리 관련 함수들',
    functions: [
      'generateExtendedMultiLayerKey',
      'validateEncryptedKey',
      'decryptKey',
      'reencryptKey',
      'analyzeKeyStrength',
      'createKeyBackup',
      'restoreKeyBackup'
    ],
    dependencies: ['EncryptionCore.gs', 'CONFIG.gs']
  };
}

/**
 * @file GroupManagement.gs
 * @brief 그룹스 관리 모듈
 * @details Google Groups 권한 관리 및 알림 기능을 담당합니다.
 * 워크스페이스 환경에서는 Admin SDK로 자동 멤버 추가, 아닌 경우 관리자 알림 이메일 전송.
 * @author Hot Potato Team
 * @date 2024
 */

/**
 * Admin SDK로 그룹에 멤버 추가 (워크스페이스 전용)
 * @param {string} userEmail - 추가할 사용자 이메일
 * @param {string} groupEmail - 그룹 이메일
 * @returns {{ success: boolean, error?: string }}
 */
function addMemberToGroupViaAdminApi(userEmail, groupEmail) {
  try {
    if (typeof AdminDirectory === 'undefined' || !AdminDirectory.Members) {
      return { success: false, error: 'Admin SDK를 사용할 수 없습니다.' };
    }
    const member = { email: userEmail, role: 'MEMBER' };
    AdminDirectory.Members.insert(member, groupEmail);
    return { success: true };
  } catch (e) {
    if (e.message && (e.message.indexOf('Member already exists') >= 0 || e.message.indexOf('memberAlreadyExists') >= 0)) {
      return { success: true };
    }
    logWarn_('GroupManagement', 'Admin API 그룹 멤버 추가 실패:', e.message);
    return { success: false, error: e.message };
  }
}

/**
 * 그룹스 권한과 함께 사용자 승인
 * @param {string} studentId - 학생 ID
 * @param {string} groupRole - 그룹스 역할
 * @returns {Object} 승인 결과
 */
function approveUserWithGroup(studentId, groupRole) {
    try {
      
      if (!studentId) {
        return {
          success: false,
          message: '학생 ID가 필요합니다.'
        };
      }
      
      if (!groupRole) {
        return {
          success: false,
          message: '그룹스 역할이 필요합니다.'
        };
      }
      
      // 1. 사용자 승인 (UserApproval.gs의 approveUser 함수 호출)
      const approvalResult = approveUser(studentId);
      if (!approvalResult.success) {
        return approvalResult;
      }
      
      // 2. 그룹스 권한에 따른 그룹스 이메일 매핑
      const groupEmail = getGroupEmailByRole(groupRole);
      const groupName = getGroupNameByRole(groupRole);
      
      if (!groupEmail) {
        return {
          success: false,
          message: '유효하지 않은 그룹스 권한입니다.'
        };
      }
      
      // 3. 사용자 이메일 복호화
      const userEmail = decryptEmailMain(approvalResult.user.google_member);
      
      // 4. 워크스페이스 환경: Admin API로 자동 멤버 추가 시도
      const addResult = addMemberToGroupViaAdminApi(userEmail, groupEmail);
      let status = 'NOTIFICATION_SENT';
      let resultMessage = '사용자가 승인되었습니다. 그룹스 관리자에게 알림이 전송되었습니다.';
      
      if (addResult.success) {
        status = 'MEMBER_ADDED';
        resultMessage = '사용자가 승인되었습니다. 그룹스에 자동으로 추가되었습니다.';
