function getKeyVerificationInfo() {
  return {
    version: '1.0.0',
    description: '관리자 키 검증 관련 함수들',
    functions: [
      'verifyAdminKey',
      'decryptAndVerifyKey',
      'analyzeKeyStrength',
      'validateKeyFormat',
      'compareKeys'
    ],
