/**
 * 사용자 row의 승인 상태 읽기 (approval / Approval 호환)
 * @param {Object} user
 * @returns {string}
 */
function getUserApprovalStatus(user) {
  return String(
    (user && (user.approval !== undefined ? user.approval : user.Approval)) || ''
  ).trim().toUpperCase();
}

/**
 * 헤더에서 승인 컬럼 인덱스 찾기 (approval / Approval 호환)
 * @param {string[]} header
 * @returns {number}
 */
function findApprovalColumnIndex(header) {
  if (!header || !header.length) return -1;
  let idx = header.indexOf('approval');
  if (idx !== -1) return idx;
  idx = header.indexOf('Approval');
  if (idx !== -1) return idx;
  return header.findIndex((h) => String(h || '').toLowerCase().includes('approval'));
}

/**
 * 모든 사용자 목록 조회 (승인 대기 + 승인된 사용자)
 * @returns {Object} 모든 사용자 목록
 */
function getAllUsers() {
  let spreadsheetId = 'unknown';
  let sheetName = 'unknown';
  
  try {
    
    // 연결된 스프레드시트 사용
    const spreadsheet = getHpMemberSpreadsheet();
    if (!spreadsheet) {
      return {
        success: false,
        message: '스프레드시트를 찾을 수 없습니다.'
      };
    }
    spreadsheetId = spreadsheet.getId();
    
    // 스크립트 속성에서 시트 이름 가져오기
    sheetName = PropertiesService.getScriptProperties().getProperty('SHEET_NAME_USER') || 'user';
    const data = getSheetData(spreadsheetId, sheetName, 'A:G');
    
    if (!data || data.length <= 1) {
      return {
        success: true,
        users: [],
        message: '사용자가 없습니다.'
      };
    }
    
    const header = data[0];
    
    // 빈 행 필터링 (학번이 없거나 이름이 없는 행 제외)
    const validRows = data.slice(1).filter(row => {
      const studentId = row[0]; // no_member
      const name = row[2]; // name_member
      return studentId && studentId !== '' && name && name !== '';
    });
    
    const users = validRows.map((row, index) => {
      const user = {};
      header.forEach((key, hIndex) => {
        user[key] = row[hIndex];
      });
      return {
        ...user,
        rowIndex: index + 2,
        id: user.no_member || `user_${index}`,
        email: user.google_member ? decryptEmailMain(user.google_member) : '',
        studentId: user.no_member || '',
        name: user.name_member || '',
        userType: user.user_type || 'student',
        isAdmin: user.is_admin === 'O',
        isApproved: getUserApprovalStatus(user) === 'O',
        requestDate: user.approval_date || new Date().toISOString().split('T')[0],
        approvalDate: getUserApprovalStatus(user) === 'O' ? user.approval_date : null
      };
    });
    
    const counts = users.reduce((result, user) => {
      const status = getUserApprovalStatus(user);
      if (status === 'X') result.pending++;
      else if (status === 'O') result.approved++;
      else result.rejected++;
      return result;
    }, { pending: 0, approved: 0, rejected: 0 });
    
    const response = {
      success: true,
      users: users,
      total: users.length,
      message: `전체 ${users.length}명 (승인 대기: ${counts.pending}명, 승인됨: ${counts.approved}명, 거부됨: ${counts.rejected}명)`
    };
    return response;
    
  } catch (error) {
    logError_('UserApproval', '모든 사용자 목록 조회 오류:', error);
    return {
      success: false,
      message: '사용자 목록 조회 중 오류가 발생했습니다: ' + error.message
    };
  }
}

