/**
 * WorkflowSpreadsheet.gs
 * 워크플로우 스프레드시트 및 시트 관리
 * Hot Potato Document Workflow Management System
 */

// ===== 워크플로우 스프레드시트 관리 =====

var workflowSpreadsheetMemo_ = null;
var WORKFLOW_SPREADSHEET_CACHE_PREFIX_ = 'workflowSpreadsheetId:';

function workflowSpreadsheetCacheKey_(rootFolderId) {
  return WORKFLOW_SPREADSHEET_CACHE_PREFIX_ + rootFolderId;
}

/**
 * 워크플로우 스프레드시트 이름 가져오기 (Script Properties 또는 기본값)
 * @returns {string} 스프레드시트 이름
 */
function getWorkflowSpreadsheetName() {
  const name = PropertiesService.getScriptProperties().getProperty('WORKFLOW_SPREADSHEET_NAME');
  return name || 'workflow';
}

/**
 * 워크플로우 스프레드시트 가져오기 (없으면 생성)
 * @returns {Object} 스프레드시트 객체
 */
function getWorkflowSpreadsheet() {
  if (workflowSpreadsheetMemo_) return workflowSpreadsheetMemo_;

  try {
    const spreadsheetName = getWorkflowSpreadsheetName();
    const cache = CacheService.getScriptCache();

    // 루트 폴더에서 먼저 찾기
    const rootFolderName = PropertiesService.getScriptProperties().getProperty('ROOT_FOLDER_NAME') || 'hot_potato_remake';
    const rootFolderId = getProjectRootFolderId_();
    let rootFolder = null;
    if (rootFolderId) {
      try {
        rootFolder = DriveApp.getFolderById(rootFolderId);
      } catch (error) {
        logWarn_('WorkflowSpreadsheet', '캐시된 루트 폴더를 열 수 없어 이름으로 다시 찾습니다:', error.message);
      }
    }
    if (!rootFolder) rootFolder = getFolderByName(rootFolderName);

    const cacheKey = rootFolder ? workflowSpreadsheetCacheKey_(rootFolder.getId()) : null;
    const cachedId = cacheKey ? cache.get(cacheKey) : null;
    if (cachedId) {
      try {
        workflowSpreadsheetMemo_ = SpreadsheetApp.openById(cachedId);
        return workflowSpreadsheetMemo_;
      } catch (error) {
        cache.remove(cacheKey);
      }
    }

    let spreadsheetId = null;
    
    if (rootFolder) {
      // workflow 폴더에서 먼저 찾기 (새 구조: workflow/ 폴더에 workflow 스프레드시트)
      const workflowFolderName = PropertiesService.getScriptProperties().getProperty('WORKFLOW_FOLDER_NAME') || 'workflow';
      let searchFolder = rootFolder;
      const workflowFolders = rootFolder.getFoldersByName(workflowFolderName);
      if (workflowFolders.hasNext()) {
        searchFolder = workflowFolders.next();
      }
      const files = searchFolder.getFilesByName(spreadsheetName);
      const foundFiles = [];
      while (files.hasNext()) {
        const file = files.next();
        if (file.getMimeType() === MimeType.GOOGLE_SHEETS) {
          foundFiles.push(file);
        }
      }
      
      if (foundFiles.length > 0) {
        // 첫 번째 파일 사용
        spreadsheetId = foundFiles[0].getId();
        logDebug_('WorkflowSpreadsheet', '워크플로우 스프레드시트 찾음:', spreadsheetId);
        
        // 중복 파일이 있으면 경고
        if (foundFiles.length > 1) {
          logWarn_('WorkflowSpreadsheet', '같은 이름의 워크플로우 스프레드시트가 여러 개 있습니다:', foundFiles.length);
          logWarn_('WorkflowSpreadsheet', '첫 번째 파일 사용:', spreadsheetId);
        }
      }
    }
    
    // 루트 폴더에서 찾지 못했으면 전체 Drive에서 찾기 (fallback)
    if (!spreadsheetId) {
      logDebug_('WorkflowSpreadsheet', '루트 폴더에서 찾지 못함, 전체 Drive에서 검색...');
      const foundId = getSheetIdByName(spreadsheetName);
      if (foundId) {
        // 찾은 스프레드시트가 루트 폴더에 있는지 확인
        if (rootFolder) {
          try {
            const file = DriveApp.getFileById(foundId);
            const parents = file.getParents();
            let isInRootFolder = false;
            
            while (parents.hasNext()) {
              const parent = parents.next();
              if (parent.getId() === rootFolder.getId()) {
                isInRootFolder = true;
                break;
              }
            }
            
            if (isInRootFolder) {
              // 루트 폴더에 있으면 사용
              spreadsheetId = foundId;
              logDebug_('WorkflowSpreadsheet', '워크플로우 스프레드시트 찾음 (전체 Drive, 루트 폴더):', spreadsheetId);
            } else {
              // 루트 폴더에 없으면 이동 후 사용
              try {
                file.moveTo(rootFolder);
                spreadsheetId = foundId;
                logDebug_('WorkflowSpreadsheet', '워크플로우 스프레드시트를 루트 폴더로 이동:', rootFolderName);
              } catch (error) {
                logWarn_('WorkflowSpreadsheet', '워크플로우 스프레드시트 폴더 이동 실패:', error.message);
                // 이동 실패해도 사용 (다른 폴더에 있을 수 있음)
                spreadsheetId = foundId;
                logDebug_('WorkflowSpreadsheet', '워크플로우 스프레드시트 찾음 (다른 폴더):', spreadsheetId);
              }
            }
          } catch (error) {
            logWarn_('WorkflowSpreadsheet', '스프레드시트 확인 실패:', error.message);
            // 확인 실패해도 사용
            spreadsheetId = foundId;
            logWarn_('WorkflowSpreadsheet', '워크플로우 스프레드시트 확인 실패, 캐시 결과 사용');
          }
        } else {
          // 루트 폴더를 찾을 수 없으면 그냥 사용
          spreadsheetId = foundId;
          logDebug_('WorkflowSpreadsheet', '워크플로우 스프레드시트 찾음 (루트 폴더 없음):', spreadsheetId);
        }
      }
    }
    
    // 여전히 찾지 못했으면 생성
    if (!spreadsheetId) {
      const newSpreadsheet = SpreadsheetApp.create(spreadsheetName);
      spreadsheetId = newSpreadsheet.getId();
      
      // 기본 시트1 삭제 (필요한 시트는 나중에 생성됨)
      try {
        const sheets = newSpreadsheet.getSheets();
        if (sheets.length > 0 && sheets[0].getName() === '시트1') {
          newSpreadsheet.deleteSheet(sheets[0]);
        }
      } catch (error) {
        logWarn_('WorkflowSpreadsheet', '기본 시트1 삭제 실패 (무시됨):', error.message);
      }
      
      // workflow 폴더로 이동 (새 구조)
      if (rootFolder) {
        try {
          const workflowFolderName = PropertiesService.getScriptProperties().getProperty('WORKFLOW_FOLDER_NAME') || 'workflow';
          let targetFolder = rootFolder;
          const workflowFolders = rootFolder.getFoldersByName(workflowFolderName);
          if (workflowFolders.hasNext()) {
            targetFolder = workflowFolders.next();
          } else {
            targetFolder = rootFolder.createFolder(workflowFolderName);
          }
          const file = DriveApp.getFileById(spreadsheetId);
          file.moveTo(targetFolder);
          logDebug_('WorkflowSpreadsheet', '워크플로우 스프레드시트를 workflow 폴더로 이동');
        } catch (error) {
          logWarn_('WorkflowSpreadsheet', '워크플로우 스프레드시트 폴더 이동 실패 (무시됨):', error.message);
        }
      }
    }
    
    workflowSpreadsheetMemo_ = SpreadsheetApp.openById(spreadsheetId);
    if (cacheKey) cache.put(cacheKey, spreadsheetId, 6 * 60 * 60);
    return workflowSpreadsheetMemo_;
    
  } catch (error) {
    logError_('WorkflowSpreadsheet', '워크플로우 스프레드시트 조회/생성 오류:', error);
    throw new Error('워크플로우 스프레드시트를 가져오거나 생성할 수 없습니다: ' + error.message);
  }
}

/**
 * 워크플로우 스프레드시트 ID 가져오기
 * @returns {string} 스프레드시트 ID
 */
function getWorkflowSpreadsheetId() {
  try {
